p=Path('design-development/whole-home-m3/group4')
def read(n):return json.loads((p/n).read_text())
def data(n,m='image/png'):return 'data:'+m+';base64,'+base64.b64encode((p/n).read_bytes()).decode()
frames={r['frame_id']:{'src':data('frames/'+r['png']),'camera':r['camera_sha256'],'snapshot':r['full_snapshot_sha256'],'night':r['camera']['viewer']['night'],'sha256':r['png_sha256']} for r in read('RENDER_EVIDENCE.json')['frames']}
op,storage,holds,verification=read('OPERATIONS.json'),read('STORAGE_AND_USE.json'),read('SITE_HOLDS.json'),read('VERIFICATION.json')
plans=[('workflow','التحضير والغسيل والسطح المتاح'),('DW','غسالة الأطباق ووقوف المستخدم'),('fridge','الثلاجة وباب المطبخ الأصلي'),('oven','حجز فرن تحت الموقد'),('washer','الغسالة وباب التراس'),('south-drawer','الدرج الجنوبي وباب الخدمة'),('slider','البديل المنزلق وفتحة الاستخدام'),('rejected-extras','سطحان إضافيان مرفوضان'),('storage','توزيع التخزين وارتفاعات الوحدات')]
planoptions=''.join(f'<option value="{n}">{t}</option>' for n,t in plans)
planhtml=''.join(f'<article class="plan" data-plan="{n}" {"" if n=="workflow" else "hidden"}><h3>{title}</h3><button class="zoomable" data-src="{data("plans/"+n+".svg","image/svg+xml")}" aria-label="تكبير {title}"><img src="{data("plans/"+n+".svg","image/svg+xml")}" alt="{title} — أبعاد نموذجية بالمليمتر"></button></article>' for n,title in plans)
holdhtml=''.join(f'<details><summary><bdi>{h["id"]}</bdi> · {h["topic"]}</summary><p>{h["measure"]}</p><p class="muted">سبب التوقف: {h["why"]}</p><p><strong>المراجعة:</strong> {h["professional"]} · مفتوح، غير معتمد.</p></details>' for h in holds['holds'])
metrics=f'<span>{verification["actual_frames"]} لقطة WebGL فعلية</span><span>{verification["plans"]} مخططات مقاسة</span><span>1241 ملف موروث محفوظ</span><span>40 بوابة موقع مفتوحة</span>'
html=r'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Type B | مجموعة4 — المطبخ</title><style>
:root{--ink:#263C32;--muted:#686E61;--paper:#F4F2EA;--line:#D7D7C9;--olive:#A8AD9C;--oak:#AE9271}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:#30352D;font:17px/1.85 Tahoma,Arial,sans-serif}h1,h2,h3,p{margin:0 0 16px}h1{font-size:clamp(28px,5vw,54px);line-height:1.35;color:var(--ink)}h2{font-size:29px;color:var(--ink)}h3{font-size:20px;color:var(--ink)}a{color:var(--ink)}bdi{direction:ltr;unicode-bidi:isolate}button,select{font:inherit;color:var(--ink);background:#FAF9F4;border:1px solid #BAC1B1;border-radius:9px;padding:8px 15px;cursor:pointer}button:hover,button:focus-visible,a:focus-visible,select:focus-visible{outline:2px solid var(--oak);outline-offset:3px}button.active{background:var(--ink);color:white}img{display:block;width:100%;height:auto}main{max-width:1220px;margin:auto;padding:28px}.eyebrow{letter-spacing:.06em;font-size:14px;color:var(--muted)}.hero{display:grid;grid-template-columns:1fr 1.18fr;gap:32px;align-items:center;padding:26px 0}.hero img{border-radius:15px}.badge{display:inline-block;background:#E4E8DB;color:var(--ink);padding:6px 12px;border-radius:18px;font-size:14px}.lead{font-size:20px}.metrics,.controls,.chips{display:flex;gap:10px;flex-wrap:wrap}.metrics span{border:1px solid var(--line);padding:6px 12px;border-radius:15px;font-size:14px}nav{position:sticky;top:0;background:#F4F2EAF2;backdrop-filter:blur(9px);z-index:2;display:flex;gap:18px;padding:12px 28px;overflow-x:auto;border-bottom:1px solid var(--line)}nav a{white-space:nowrap;text-decoration:none;font-size:15px}section{padding:38px 0;border-bottom:1px solid var(--line);scroll-margin-top:70px}.card{background:#FBFAF5;border:1px solid var(--line);border-radius:14px;padding:25px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.muted{color:var(--muted);font-size:15px}.important{border-right:5px solid var(--oak);padding:16px 22px;background:#EEEADD;margin:20px 0}.warn{border-right-color:#A57762}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}figure{margin:0}figcaption{font-size:14px;color:var(--muted);padding:10px 0}.zoomable{padding:0;width:100%;border:0;background:transparent}.zoomable img{border-radius:10px}table{width:100%;border-collapse:collapse;font-size:15px}td,th{text-align:right;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#E9ECDf;color:var(--ink)}.tablewrap{overflow-x:auto}.plan{background:#FBFAF5;border:1px solid var(--line);border-radius:12px;padding:20px}.plan img{aspect-ratio:890/700;object-fit:contain}.swatch{display:inline-flex;align-items:center;gap:8px;font-size:14px}.swatch i{width:25px;height:25px;border:1px solid #7775;border-radius:50%}details{background:#FBFAF5;border:1px solid var(--line);padding:15px 20px;border-radius:10px;margin:12px 0}summary{cursor:pointer;color:var(--ink);font-weight:bold}details p{margin-top:14px}ol,ul{padding-right:24px}li{margin:7px 0}dialog{width:min(96vw,1500px);height:94vh;padding:15px;border:1px solid var(--line);border-radius:12px;background:#FAF9F4}dialog::backdrop{background:#18291BE0}#zoomArea{height:calc(100% - 65px);overflow:auto;direction:ltr}#zoomImage{width:100%;max-width:none;transform-origin:top left}#proof{font:12px/1.6 monospace;direction:ltr;text-align:left;overflow-wrap:anywhere}.small{font-size:14px}.footer{padding:35px 0;color:var(--muted);font-size:14px}@media(max-width:780px){main{padding:18px}.hero,.grid,.pair{grid-template-columns:1fr}.hero{gap:20px}nav{padding:10px 18px;gap:15px}.card{padding:19px}table{min-width:670px}body{font-size:16px}h2{font-size:25px}.controls button{font-size:14px;padding:7px 9px}}@media print{nav,.controls,dialog{display:none}section{break-inside:avoid}.hero,.grid,.pair{grid-template-columns:1fr 1fr}body{font-size:12px}}
</style></head><body><nav aria-label="تنقل المراجعة"><a href="#vision">التوصية</a><a href="#visual">الصور المقارنة</a><a href="#daily">الاستخدام اليومي</a><a href="#plans">المخططات</a><a href="#storage">التخزين</a><a href="#finish">الخامة والضوء</a><a href="#holds">بوابات الموقع</a></nav><main>
<header id="vision"><p class="eyebrow"><bdi>TYPE B · M3 GROUP 4 · 12 OCT 2026 / CAIRO</bdi></p><div class="hero"><div><span class="badge">توصية مؤقتة للتطوير — لا تنفيذ أو شراء</span><h1>عاجي دافي، بلوط هادي<br>وحجر بلمسة زيتية</h1><p class="lead">مطبخ عائلي متماسك مع الاستقبال وغرف النوم وحمامات المجموعة الثالثة: واجهات مقفولة، خشب محدود، أسطح تحضير فاضية وإضاءة مهمة قريبة من الشغل.</p><p>الأفضل بصريًا هو تشطيب A والعلوي المقفول. وللطاسات والأطباق، أفضل الأدراج كاملة العرض من B <strong>بشرط نجاح بروفة باب التراس والمستخدم</strong>. اللقطة المقترحة بتجمع اختيارات محلية سبق اختبارها؛ مش بديل ثالث أو تخطيط جديد.</p></div><button class="zoomable" data-frame="RECOMMENDED-sink" aria-label="تكبير التوصية"><img id="heroImage" alt="التوصية المؤقتة — التقاط WebGL حقيقي من المصدر"></button></div><div class="metrics">__METRICS__</div><div class="important">المطبخ الأصلي المغلق محفوظ. الأجهزة والخدمات في نفس المراكز، والسقف الداخلي 2500 مم. كل الموافقات والتنفيذ وP1 وتغيير السحابة لسه HOLD. الأدراج مش حل تلقائي لحركة شخصين أو باب الخدمة.</div></header>
<section id="visual"><p class="eyebrow">صور فعلية / كاميرا وحالة ضلف متطابقتان لكل مقارنة نهائية</p><h2>شوف المصدر، القادة السابقين، والتحسين</h2><p>المصدر هو v55 المحلي؛ «القادة» يعزلوا ألوان المطبخ R4 وبابي R5 D1 ومهمة R6 L2 داخل نفس الشقة الأصلية. تغييرات الاستقبال في A/P0 القديم لم تُستورد. A يدرس الواجهة المنزلقة، B يدرس الأدراج وكُوّة عرض واحدة. التوصية تجمع تشطيب وعلوي A مع أدراج B.</p><div class="controls" id="comparisons"><button data-mode="source" class="active">المصدر ← التوصية</button><button data-mode="lead">R4/R5/R6 ← التوصية</button><button data-mode="options">A ← B</button><button data-mode="storage">A المنزلق ← التوصية</button><select id="camera" aria-label="اختيار الكاميرا"><option value="sink">الحوض والضلعين</option><option value="work">التحضير والموقد</option><option value="night">نفس منظور العمل مساءً</option><option value="access">الثلاجة وباب الدخول</option><option value="entry">العلاقة من الاستقبال</option></select></div><div class="pair"><figure><button class="zoomable" id="leftButton" aria-label="تكبير المقارنة الأولى"><img id="leftImage" alt="المقارنة الأولى"></button><figcaption id="leftLabel"></figcaption></figure><figure><button class="zoomable" id="rightButton" aria-label="تكبير المقارنة الثانية"><img id="rightImage" alt="المقارنة الثانية"></button><figcaption id="rightLabel"></figcaption></figure></div><p class="muted">كل صورة 1280×720 من Three.js/WebGL الحقيقي؛ لا صورة توليدية. الفرن وداخل الحوض والواجهات تفاصيل عامة داخل الأبعاد الأصلية، وليست أجهزة أو فتحات تركيب معتمدة. باب التراس مغلق فعلًا في المقارنات النهائية، لم يُخفَ أو يُحذف.</p><details><summary>هوية الصور المختارة</summary><div id="proof"></div></details></section>
<section id="daily"><h2>الحركة اليومية أهم من الأبواب المقفولة</h2><div class="grid"><article class="card"><h3>التحضير والغسيل والطبخ</h3><ol><li>طلّع الطعام من الثلاجة على landing الحالي 600×410، واقفل الثلاجة قبل تحريك باب المطبخ.</li><li>اغسل في الحوض، واستخدم landing مؤقتًا للتصفية أو الأشياء النظيفة؛ افصل جلسة الطعام النظيف عن الأدوات المتسخة.</li><li>خلي جنوب الموقد 593×600 فاضي للتحضير: لوح افتراضي 400×300 يترك 96.5 مم عند كل طرف. المسافة دي ليست اعتماد حرارة أو مقابض طاسات.</li><li>شيل لوح التحضير قبل وضع حلة ساخنة. الجزء الشمالي 307 مم محدود؛ ما تحوّلهوش لكوفي ثابت أو مكان كل الأجهزة الصغيرة.</li></ol><p class="muted">حوض550 داخل قاعدة600 يترك25 مم عند كل جانب فقط. شريط105 مم أمام/خلف هو فرق الأظرف، وليس سطحًا جافًا كاملًا صالحًا لوضع كل الأدوات.</p></article><article class="card"><h3>تعبئة DW وتفريغها</h3><p>اجمع البواقي في حاوية قابلة للفك تحت الحوض، ثم حمّل الجهاز. فرّغ الأطباق على دفعات؛ اقفل الرف والضلفة قبل الدوران للدرج الجنوبي. فتح DW والدرج مع مستخدمين في نفس الوقت يتداخل في الاختبار.</p><p>حد الباب السابق 600 مم يترك972.3 مم حتى الوجه الجنوبي المفترض. مع مستخدم600×600، الباقي372.3 مم؛ مش مساحة مرور مريحة مثبتة لشخص تاني.</p><p class="muted">زيادة افتراضية200 مم للرف/وضع الوقوف تقلل النطاق إلى172.3 مم وتُنتج21/91 تداخلًا مع باب الخدمة. ده stress test؛ امتداد رف المنتج الفعلي غير معلوم.</p></article></div><div class="tablewrap"><table><thead><tr><th>الحالة</th><th>نتيجة جديدة من المصدر</th><th>القرار المؤقت</th></tr></thead><tbody><tr><td>الثلاجة650 المفترضة</td><td>52/91 تداخل لوح و15/91 جسم مع باب الدخول</td><td>جهة المفصلة والمقابض والتهوية HOLD؛ لا تدخل أثناء الفتح</td></tr><tr><td>الغسالة الداخلية</td><td>36/91 تداخل مستخدم600 مع باب التراس</td><td>تتابع الاستخدام؛ النيش محفوظ، لا نقل للتراس</td></tr><tr><td>فرن تحت الموقد</td><td>الحد المفترض500 لا يصطدم بلوح باب الخدمة في العينات، لكن جسم فرن/غسالة يتداخل39700 مم²</td><td>حجز تحت الموقد، مش فرن مختار أو تشغيل شخصين مثبت</td></tr><tr><td>درج الجنوب450</td><td>68/91 تداخل اللوح، و47/91 جسم600 مع باب التراس</td><td>راحة الوصول أفضل؛ تصنعه فقط بعد بروفة وتشغيل باب مقبول</td></tr><tr><td>المنزلق12</td><td>0/91 لوح، لكن75/91 جسم600؛ فتحة269.5 أصغر من طبق280 وطاسة300</td><td>مرفوض كتخزين يومي شامل؛ ميل القطع الثقيلة غير مثبت</td></tr><tr><td>landing درج300</td><td>0/91 لوح مع باب الدخول؛ المستخدم يتداخل48/91</td><td>أغلق باب/ثلاجة قبل الاستخدام؛ لا ادعاء استقلال المرور</td></tr></tbody></table></div><p class="muted">91 وضعًا عند1° مع ضلفة غرفة40 مم. دي حسابات أجسام مستطيلة، مش بشر متحركين أو مساحة أمان/كود. عدم تصادم لوح لا يعني راحة المستخدم.</p><div class="important warn">مسار500/600 في الاختبار المحافظ متاح بين نقطتي اقتراب داخل الغرفة عند غلق الأجهزة، وحتى مع باب DW وحده. عند تفريغ DW تصبح نقطة اقتراب باب الخدمة المختارة محجوبة. نقطة البداية700 محجوبة؛ لا ننسب ده لاستحالة كل المسارات. الضلفة الأصلية للدخول مفتوحة والخدمة مغلقة في الاختبار، والعتبات والمرور الفعلي لم يُعتمدا.</div><details><summary>الحدود الطولية من دراسة المصنع السابقة محفوظة</summary><p>راجعنا نفس أمثلة LG الموجودة في Sprint5، من غير بحث جديد أو اختيار SKU: زيادة440 مم لغسالة و499 مم لثلاجة. مع نفس واجهات وعروض المصدر600/650، مستخدم الغسالة يتداخل26/91 مع باب الخدمة، ولوح الثلاجة40/91 ومستخدمها32/91 مع باب الدخول. دي حدود طولية وليست أقواس مفصلات مصنّع؛ تغيير العمق يغيّر موضع الوقوف ولا يضمن تحسن كل الحالات.</p></details><h3>السفرة جزء من الاستخدام، وليست مساحة احتياطية مجانية</h3><p>ربطنا المخطط بدراسة B2 المستقلة: ست كراسي و2000×950 للطاولة، مع سحب450 مفترض. المقترح لم يتنقل إلى snapshots المطبخ. صينية700 داخل فتحة720.2 تترك20.2 مم إجمالًا قبل أي jamb أو مقبض؛ ده تحذير للبروفة، مش إثبات مرور. تخزين الأطباق اليومية في المطبخ يقلل الحمل المتكرر للسفرة؛ محتويات البوفية المخفضة ما زالت محتاجة قرار منفصل.</p></section>
<section id="plans"><h2>مخططات تقرأها وتراجعها</h2><p>اضغط للتكبير. أبعاد بالمليمتر من المصدر؛ الذهبي حركة الباب، الأزرق حد الجهاز، والأحمر مساحة المستخدم الافتراضي. درجات الغلق/الفتح هنا دليل تشغيلي؛ مش رسومات نجارة تنفيذية.</p><div class="controls"><label for="planSelect">المخطط:</label><select id="planSelect" aria-label="اختيار مخطط التشغيل">__PLAN_OPTIONS__</select></div><div class="planGrid">__PLANS__</div><div class="important warn">اختبرنا سطحين فقط: جزيرة1000×500 وكاونتر جنوبي1000×350. الاتنين يتداخلوا مع استخدام DW والدرج، والجزيرة كمان مع مستخدم الفرن؛ مرفوضان. لم نرسم شكلًا جذابًا يخفي أزمة التشغيل.</div></section>
<section id="storage"><h2>كل وحدة لها وظيفة — من غير سعة متخيلة</h2><div class="tablewrap"><table><thead><tr><th>الوحدة القائمة</th><th>التوزيع العملي المقترح</th><th>ما يلزم التحقق منه</th></tr></thead><tbody><tr><td>شمالي1800×330×700</td><td>أكواب وأطباق خفيفة/بولة ومواد جافة، اليومي أسفل والموسمي أعلى. أفضل全部 مقفول</td><td>ارتفاع1480–2180 وتجربة وصول أفراد البيت؛ أعلى الوحدات320 تحت السقف يحتاج تنظيف</td></tr><tr><td>علوي غربي300 و450</td><td>شاي/إمدادات خفيفة فقط</td><td>حركة الضلف على ارتفاع الرأس، حمل وتثبيت وحرارة الهود</td></tr><tr><td>جنوب593</td><td>أدراج: قطع صغيرة أعلى، أطباق يومية وسط، طاسات أسفل.557 عرض داخلي و500 عمق مجرد افتراض</td><td>طبق280، طاسة300 مع المقابض، وزن ومقسمات وسحب450 وباب التراس</td></tr><tr><td>شمال307</td><td>أدوات صغيرة أو توابل، من غير وعد بسحب ركن في نفس الموضع</td><td>271 داخلي مفترض، حرارة ومساحة آلية وmaintenance</td></tr><tr><td>landing600×410</td><td>شاي/فطار جاف وقماش؛ السطح فاضي لرفع الأطباق والطعام</td><td>564×374 افتراضي، درج300 وباب الدخول؛ جهاز كوفي غير مخصص</td></tr><tr><td>تحت الحوض600×610</td><td>السيفون والمحابس أولًا، بعدها حاوية مخلفات قابلة للفك ومواد تنظيف منفصلة عن الطعام</td><td>حاوية220×300×330 مجرد اختبار حجم؛ الصرف الحقيقي غير مرسوم، لا لتر معتمد</td></tr><tr><td>ركن600×590</td><td>صفر سعة يومية محسوبة حتى يثبت الوصول</td><td>ضلفتان جنوبيتان محتملتان تصطدمان بالغربي في91/91؛ blind-corner CAD ونظافة فعلية</td></tr><tr><td>DW / غسالة / حجز فرن</td><td>صفر تخزين دولاب</td><td>الموديل المغلق ليس تجويف تركيب ولا مساحة مخزون</td></tr></tbody></table></div><p>درسنا جهتي فتح الواجهات العلوية في نطاق1480–2180. ضلفة الشرق600 المفترضة تتقاطع في المسقط مع وقفة الحوض في38/91 أو52/91 حسب جهة المفصلة. ده تنبيه لبروفة الرأس واليد، وليس حساب إصابة رأس. مركز مستخدم DW المفتوح يبعد نحو1210 مم في المسقط عن مركز واجهة العلوي؛ اقفل الجهاز وتحرك لاستعمال الخزانة بدل مد اليد من خلفه. كل عدد ضلف وتقسيمة ومفصلة ظاهرين فرضية نجارة.</p><div class="grid"><article class="card"><h3>المقفل أم جزء عرض صغير؟</h3><p>A يحافظ على عرض علوي مقفول كامل. B يحوّل300 مم فقط إلى كُوّة بلوط للأكواب القليلة؛ أهدأ من رفوف مفتوحة كثيرة، لكنه يجمع الغبار ويحتاج مسحًا متكررًا.</p><p>افتراض carcass18 يعطي344.36 لتر حجم هندسي إجمالي مقفول في A مقابل285.79 في B؛ نحو58.57 ينتقل للعرض المفتوح. مش صافي سعة بعد الأرفف والمفصلات أو عدد قطع مثبت.</p><p><strong>التوصية:</strong> المقفول لحين جرد احتياجات الأسرة. الخشب السفلي يوفر الدفء من غير التضحية بتخزين العلوي.</p></article><article class="card"><h3>تخزين البيت لا يُرحّل تلقائيًا</h3><p>البوفية فقدت38.3% من العرض الصافي المفترض؛ BR02 نحو25% خارجي/25.9% صافي، والصناديق المنخفضة للماستر وBR01 نحو41.7% من الصافي المفترض. قرارات الأحذية واحتياطي WIC ما زالت مفتوحة.</p><p>المطبخ مخصص للطعام والطبخ والأطباق والتنظيف. لا احتياطي مفروشات أو ملابس محسوب فيه. الجرد ومراجعة التكامل لاحقًا يجب أن تحدد أين تذهب الأواني الموسمية التي كانت بالبوفية.</p></article></div></section>
<section id="finish"><h2>خامة متماسكة، وصيانة ممكنة</h2><div class="grid"><article class="card"><h3>A — زيتي هادي وعاجي مقفول</h3><div class="chips"><span class="swatch"><i style="background:#E8E2D7"></i>عاجي R4</span><span class="swatch"><i style="background:#AE9271"></i>بلوط محدود</span><span class="swatch"><i style="background:#A8AD9C"></i>حجر زيتي</span><span class="swatch"><i style="background:#D7D0C2"></i>سطح دافي</span></div><p>الزيتي يضيف شخصية من غير غمقان واسع، ويربط حمامات Group3 B بالحجر والخشب في الاستقبال وغرف النوم. العلوي كله عاجي، الخشب في جنوب الغربي والـlanding فقط؛ مقابض نيكل مطفي بسيطة سهلة المسك والمسح.</p></article><article class="card"><h3>B — ظهر كوارتز وكُوّة بلوط واحدة</h3><div class="chips"><span class="swatch"><i style="background:#D9D2C5"></i>ظهر دافي</span><span class="swatch"><i style="background:#D8D1C5"></i>باب R5 D1</span><span class="swatch"><i style="background:#C6C2B7"></i>أرض حجرية</span></div><p>أفتح وأكثر هدوءًا لكن أقرب للخامة المحايدة العامة. كُوّة300 توفّر حركة بصرية صغيرة بدل رفوف كاملة. الأفضل عندنا A المقفول، مع إبقاء B كاختيار ذوق واعٍ بتكلفة التخزين والنظافة.</p></article></div><p>ظهر موحد قابل للغسل بلمسة حجرية، يصل بصريًا من سطح860 إلى أسفل العلوي1480، مع نطاق70 قرب الهود. اختبرنا امتداداته حتى خلف الركن والـlanding بدل شرائط إصلاح منفصلة. عرض3000 شمالًا و2090 غربًا حدود نموذجية للكسوة المقترحة، <strong>ليست قصّات أو سماكات تنفيذ</strong>. لوح المصدر القديم محفوظ وراء طبقة العرض.</p><p>حجر فاتح قليل النقشة للسطح، أرض مطفية بلون معدني دافي وحوائط أصلية هادئة. اختبر عمليًا عينة porcelain/سطح مناسب مقابل عينة حجر حسب البقع والحمض والحرارة والصيانة؛ لا granite/quartz/porcelain SKU معتمد من لون الرندر. خشونة الصورة لا تثبت مقاومة انزلاق، ولا نوحّد أرض المطبخ/الحمام قبل اختبار المادة والمنسوب.</p><div class="grid"><article class="card"><h3>ثلاث وظائف للضوء</h3><p>عام للممر والتنظيف والثلاجة، مهمة مستقلة تحت العلوي ومهمة الهود R6 L2، ومستوى مرور هادي لو المنتج يتيح تحكمًا مناسبًا. البابين D1 ثابتان، والسقف2500 بدون نزول جديد.</p><p class="muted">مهمة تحت الوحدات لها اتجاه محفوظ وشريط45 مم خلف الحافة في R6، وليست نقطة كهرباء. المصدر يستخدم حرارة3000K كنية بصرية؛ المنتج/شدة/وهج/ماء وحرارة لازم يتراجعوا بعينة ومختص. الأشعة السابقة تثبت حجب الهود لرأس شعاع السقف، لا توزيع Lux كامل.</p></article><article class="card"><h3>تنظيف وصيانة قبل الزينة</h3><p>مسح الظهر من غير فواصل زخرفية كثيرة؛ سد مرن مناسب عند سطح/حائط بعد الرفع. حواف نجارة محمية من الماء، ركلة قابلة للفك عند الخدمة، سيفون ومحابس في متناول اليد دون إخراج الجهاز، وdriver جاف قابل للفك.</p><p>خلي المنشفة على خطاف صغير في الجانب الجاف للـlanding بعد تجربة الباب، والصابون/فرشة على صينية تُرفع للتنظيف. لا خطاف/قضيب أو كابل فوق الغاز، ولا سلة أرضية في الممر. فلتر الشفاط يتشال للتنظيف؛ مسار عادم وتعويض هواء لا يُستنتج من شكل الهود.</p></article></div></section>
<section id="critique"><h2>النقد والتصحيح — والضعف اللي لسه موجود</h2><div class="grid"><article class="card"><button class="zoomable" data-frame="A-INITIAL-work" aria-label="تكبير الالتقاط الأول"><img id="initialImage" alt="الالتقاط الأول قبل التصحيح"></button><p class="muted">الالتقاط الأول: باب التراس مفتوح يحجب الواجهة الجنوبية، ونطاقات الظهر لا تكمل كل منطقة العمل. كاميرا المكان نفسها؛ حالة الضلفة مختلفة، فلا تُخلط بالمقارنة النهائية المتطابقة.</p></article><article class="card"><ol><li>اختبار الدرج كشف حركة باب الخدمة؛ درسنا المنزلق فعليًا ثم رفضناه كحل شامل بعد قياس فتحة الاستخدام وجسم المستخدم. التوصية رجعت للأدراج بصورة مشروطة، من غير ادعاء حل المرور.</li><li>حذفنا الديكور التمثيلي حول الموقد وأبقينا سطح التحضير واضحًا. كان شرطًا في الالتقاط الأول، ولم نعتمد عليه كحيز عمل ثابت.</li><li>فتحنا الوعاء العام داخل ظل الحوض550×400، وصححنا فتحة السطح المطابقة وإزاحة الوعاء30؛ الوعاء385×264×160 افتراضي، لا اختبار تدفق أو رذاذ.</li><li>وحّدنا نطاق الظهر على كامل منطقة الكونتر الأصلية، وصححنا جسم العلوي حتى تظهر ألواح الواجهات والفواصل فعليًا داخل عمق330 نفسه؛ التقسيمات تظل افتراضًا. المقابض والخشب هدّأناهم. صور المصدر والقادة ثم A/B والتوصية جرى التقاطها بنفس الكاميرات النهائية.</li><li>أضفنا منظور الثلاجة/الدخول ولقطة مساء، وأبقينا باب الخدمة مغلقًا فعلًا في النهائي لإظهار النجارة؛ حالات الاصطدام منفصلة في المخططات.</li></ol></article></div><div class="important warn">التصميم لسه فيه قيود حقيقية: سطح تحضير صغير، مصدر DW أعلى15 مم من سطح العمل ولا يثبت لوحًا مستمرًا، corner غير مثبت الوصول، جسم المستخدم يتعارض مع الباب أثناء أكثر من عملية، ومتطلبات مواقد/عادم وصافي فتحات غير مقاسة. شكل الفرن والهود والثلاجة proxies. الصور لا تثبت انعكاس/وهج أو lux أو تكامل الأجهزة أو راحة شخصين.</div></section>
<section id="holds"><h2>ما يلزم قبل اعتماد التنفيذ</h2><p>12 بوابة للمطبخ، مع28 بوابة موروثة من Group1B/Group2/Group3 محفوظة ومفتوحة. التنفيذ يفضل بوابة Issue19 الحالية. فقدان قياس موقع لا يوقف سبرنت التراس المستقل، لكنه يمنع تحويل الصورة لطلب نجارة أو أجهزة.</p>__HOLDS__</section>
<section id="evidence"><h2>التحقق والتسليم التالي</h2><p>بدأنا من Group3 checkpoint e4bf637، المحتوي على120 إضافة، فوق فرع PR68 الحالي8b91b69. حفظنا1241/1241 ملفًا موروثًا ببايتاته، وكل الأثاث والخدمات والأبواب الأصلية. R4/R5/R6 ودليل Bosch ومتطلبات تركيب الأجهزة محفوظون ولم نعد بحث SKU.</p><p>Build والمراجعات المحلية للمشاهد والسحابة التجريبية والنجارة/الضوء والعمارة والمالك PASS. «السحابة» في الاختبار adapter محلي، لا حفظ حي. فحوص صور المجموعة الجديدة تربط PNG والكاميرا وsnapshot وهندسة المصدر والأصول، وتختبر رفض التلاعب. بعض الاختبارات التاريخية للصور تعتمد على مجلدات renders غير متتبعة غير موجودة في worktree؛ لم نزعم تشغيلها بنجاح، ولم نستبدلها بصور مفبركة.</p><p>لا Actions ولا merge ولا فرع PR مرفوع ولا deployment أو تغيير إعدادات/فوترة. PR68 يظل Draft، وهذه المراجعة المستقلة ليست ضمن فرق فرعه. أي حفظ عبر review tag مشروط بفحص triggers المنشور مع الدليل؛ حالة النشر الفعلية وروابط الـcommit تُكتب في Issue75 بعد التحقق.</p><p><strong>التسليم التالي:</strong> مجموعة5 للتراسات الثلاثة، من المصدر الأصلي ومراجعة Group4 الحالية. لا نقل غسالة تلقائي، لا صرف/تظليل/سقف/كهرباء خارجي معتمد. كل40 بوابة سابقة تظل مستقلة.</p><p class="small"><a href="https://github.com/Mostafatalaat770/flat-designer/issues/75">Issue75</a> · <a href="https://github.com/Mostafatalaat770/flat-designer/issues/72">المراجعة الحالية72</a> · <a href="https://github.com/Mostafatalaat770/flat-designer/issues/41">خارطة المالك الحالية41</a> · <a href="https://github.com/Mostafatalaat770/flat-designer/pull/68">Draft PR68</a> · <a href="https://github.com/Mostafatalaat770/flat-designer/issues/19">بوابة التنفيذ19</a></p></section><footer class="footer">ملف مستقل يعمل دون الإنترنت؛ الصور والمخططات مدمجة. قياسات نموذج مصدر مُعاير، لا رفع موقع أو اعتماد بناء. ملفات JSON وSHA ومخططات SVG ودليل التكرار داخل ZIP.</footer></main><dialog id="zoom"><div class="controls"><button id="closeZoom">إغلاق</button><button id="larger">تكبير +</button><button id="smaller">تصغير −</button><button id="fit">ملاءمة</button><span id="scaleLabel">100%</span></div><div id="zoomArea"><img id="zoomImage" alt="الصورة أو المخطط مكبّر"></div></dialog><script>
const frames=__FRAMES__;let mode='source',view='sink',scale=1;const names={SOURCE:'المصدر v55',LEAD:'R4 ivory / R5 D1 / R6 L2 — القادة السابقون',A:'A · زيتي، علوي مقفول، واجهة منزلقة للدراسة',B:'B · كوارتز، كُوّة واحدة، أدراج 450 للدراسة',RECOMMENDED:'التوصية · تشطيب وعلوي A + أدراج B المشروطة'};const pairs={source:['SOURCE','RECOMMENDED'],lead:['LEAD','RECOMMENDED'],options:['A','B'],storage:['A','RECOMMENDED']};
function update(){const [a,b]=pairs[mode],left=frames[a+'-'+view],right=frames[b+'-'+view];if(left.camera!==right.camera)throw Error('Unmatched camera');document.getElementById('leftImage').src=left.src;document.getElementById('rightImage').src=right.src;document.getElementById('leftButton').dataset.src=left.src;document.getElementById('rightButton').dataset.src=right.src;document.getElementById('leftLabel').textContent=names[a];document.getElementById('rightLabel').textContent=names[b];document.getElementById('proof').textContent='Camera SHA256: '+left.camera+'\nLeft snapshot: '+left.snapshot+'\nRight snapshot: '+right.snapshot+'\nLeft PNG: '+left.sha256+'\nRight PNG: '+right.sha256+'\nNight: '+left.night+'/'+right.night;document.querySelectorAll('#comparisons button').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;update();}));document.getElementById('camera').addEventListener('change',e=>{view=e.target.value;update();});
document.getElementById('planSelect').onchange=e=>document.querySelectorAll('.plan').forEach(p=>p.hidden=p.dataset.plan!==e.target.value);const dialog=document.getElementById('zoom'),img=document.getElementById('zoomImage');function resize(){img.style.width=(scale*100)+'%';document.getElementById('scaleLabel').textContent=Math.round(scale*100)+'%';}document.querySelectorAll('.zoomable').forEach(b=>b.addEventListener('click',()=>{img.src=b.dataset.src||(frames[b.dataset.frame]?.src);scale=1;resize();dialog.showModal();}));document.getElementById('closeZoom').onclick=()=>dialog.close();document.getElementById('larger').onclick=()=>{scale=Math.min(4,scale+.5);resize();};document.getElementById('smaller').onclick=()=>{scale=Math.max(.5,scale-.5);resize();};document.getElementById('fit').onclick=()=>{scale=1;resize();};document.getElementById('heroImage').src=frames['RECOMMENDED-sink'].src;document.getElementById('initialImage').src=frames['A-INITIAL-work'].src;update();
</script></body></html>'''
html=html.replace('全部','كله').replace('__METRICS__',metrics).replace('__PLANS__',planhtml).replace('__PLAN_OPTIONS__',planoptions).replace('__HOLDS__',holdhtml).replace('__FRAMES__',json.dumps(frames,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
# Keep every mixed Arabic/mm token directionally isolated without touching scripts/attributes.
from xml.sax.saxutils import escape
parts=re.split('(<[^>]+>)',html);in_script=False;in_style=False;in_bdi=False
for i,v in enumerate(parts):
 if v.startswith('<script'):in_script=True
 elif v.startswith('</script'):in_script=False
 elif v.startswith('<style'):in_style=True
 elif v.startswith('</style'):in_style=False
 elif v.startswith('<bdi'):in_bdi=True
 elif v.startswith('</bdi'):in_bdi=False;in_style=False;in_bdi=False
 elif i%2==0 and not in_script and not in_style and not in_bdi:
  v=re.sub(r'(?<=[\u0600-\u06ff])(?=[0-9A-Za-z])|(?<=[0-9A-Za-z])(?=[\u0600-\u06ff])',' ',v)
  # Dimensions and percentages must retain their numeric direction in RTL prose.
  v=re.sub(r'(?<![A-Za-z0-9])([0-9]+(?:[.,][0-9]+)?(?:[×/–][0-9]+(?:\.[0-9]+)?)*(?:%)?)',r'<bdi>\1</bdi>',v)
  parts[i]=v
(p/'Owner-Review.html').write_text(''.join(parts))
print('Arabic offline review bytes', (p/'Owner-Review.html').stat().st_size)
